__NUXT_JSONP__("/kr/how-to-apply/visa_overseas", (function(a){return {data:[{details:{slug:"kr",pageTitle:"장기간 등록하는 유학생 등록 | Mentor Language Institute",pageDescription:a,title:"장기간 등록하는 유학생 등록",image:"\u002Fimages\u002Fvisa-overseas\u002Fvisa.jpg",category:[{title:a,list_content:["미국 이외의 지역에 거주하는 사람","미국에 90일 이상 머무는 사람","미국의 어학원에서 공부하고 있는 사람"]},{title:"등록 절차",image:"\u002Fimages\u002Fvisa-overseas\u002Fsteps-kr.jpg",ordered_content:["MLI에 등록하기","서류 제출하기","당신의 I-20를 받습니다","비자 신청\u002F인터뷰","비자 받기","미국으로 떠나기"],content:["보통 학생비자를 받고 공부하는데 약 3개월이 걸립니다. 따라서 충분한 시간을 두고 절차를 진행하는 것을 추천합니다. 적어도 3개월전에 등록하세요. 만약 출발일로부터 3개월도 안남아서 지원 한다면, 저희 스탭들에게 알려주세요."]},{title:"등록 후에 스텝에 관해서",image:"\u002Fimages\u002Fvisa-overseas\u002Fmli-short-en.jpg",content:["학생은 등록 후에,iMLI시스템이 등록을 처리 할 것입니다.\u003Cbr \u002F\u003E학생은 iMLI에 열거되어 있는데로 순서를 따르면 됩니다."]},{title:"온라인 지원",content:["당신의 비자에 대한 정보를 입력하세요.\u003Cbr \u002F\u003E모든 문의를 iMLI통해서 하세요.","아래에서 신청하세요."]}],btn_label:"온라인 지원서",admission:{link:"\u002Fkr\u002Fadmission",content:["*신용카드를 가지고 있어야 합니다."]},dir:"\u002Fvisa-overseas",path:"\u002Fvisa-overseas\u002Fkr",extension:".json",createdAt:"2026-10-22T16:31:31.335Z",updatedAt:"2025-05-26T12:06:28.031Z"}}],fetch:{},mutations:void 0}}("어떤 학생이 학생비자 등록하는데 적합하나요?")));